"""Offline, self-contained dashboard; all candidate text is escaped."""
import json


def render(data):
    payload=json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
    return TEMPLATE.replace('__STUDY_DATA__',payload)


TEMPLATE=r'''<!doctype html>
<html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>HPC Forest — historique comparé</title>
<style>
:root{color-scheme:light;--ink:#122936;--muted:#526776;--line:#dce4e8;--blue:#087cba;--green:#057463;--soft:#f0f5f7;--red:#a83232}*{box-sizing:border-box}body{margin:0;background:#f5f7f8;color:var(--ink);font:15px/1.55 system-ui,-apple-system,Segoe UI,sans-serif}header{background:#102c3b;color:white;padding:32px max(26px,calc((100vw - 1360px)/2));border-bottom:5px solid #25c7af}header .eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.18em;color:#8ce0da}h1{font-size:clamp(26px,3vw,42px);line-height:1.2;margin:10px 0}header p{max-width:900px;color:#cee1e8;margin:8px 0}main{max-width:1412px;margin:auto;padding:24px 26px 70px}h2{font-size:25px;margin:0 0 14px}h3{font-size:18px;margin:22px 0 8px}p{margin:8px 0 16px}.muted{color:var(--muted)}nav{display:flex;gap:5px;flex-wrap:wrap;margin-bottom:23px;border-bottom:1px solid var(--line);padding-bottom:12px}button,select,input{font:inherit;border-radius:7px;border:1px solid #b9ccd5;padding:8px 12px;background:white;color:var(--ink)}button{cursor:pointer}nav button{border-color:transparent;background:transparent}nav button.active{background:#102c3b;color:white}button:hover{border-color:var(--blue)}button:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid #45b9eb;outline-offset:2px}a{color:#006c9f;text-decoration-thickness:1px;text-underline-offset:3px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card,.panel{background:white;border:1px solid var(--line);border-radius:12px;padding:20px;margin-bottom:20px}.stat{font-size:32px;font-weight:750;line-height:1.2;letter-spacing:-.025em}.card p{font-size:13px;margin:6px 0 0;color:var(--muted)}.notice{border-left:4px solid var(--green);background:#e8f5f1;padding:13px 17px;border-radius:5px;margin:15px 0}.two{display:grid;grid-template-columns:1.1fr 1fr;gap:20px}.toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:12px 0 18px}.toolbar label{font-size:13px;font-weight:600}.toolbar input{min-width:240px}table{border-collapse:collapse;width:100%;font-size:13px;font-variant-numeric:tabular-nums}th,td{padding:10px 11px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}th{background:#edf3f5;position:sticky;top:0;z-index:1;font-size:12px;color:#355466;white-space:nowrap}td.num,th.num{text-align:right}tbody tr:hover{background:#f3f9fb}.table-scroll{overflow:auto;max-height:660px;border:1px solid var(--line);border-radius:7px}code{font:12px ui-monospace,SFMono-Regular,Consolas,monospace;background:#edf2f4;padding:2px 4px;border-radius:3px}pre{white-space:pre-wrap;word-break:break-word;font:12px/1.6 ui-monospace,Consolas,monospace;background:#0f2632;color:#deedf3;border-radius:8px;padding:18px;overflow:auto;max-height:520px}small{font-size:12px}.badge{display:inline-block;border-radius:99px;background:#e3f3eb;color:#075c40;padding:2px 9px;font-size:12px;white-space:nowrap}.badge.bad{background:#fcebea;color:var(--red)}.badge.pending{background:#fff2d3;color:#785200}.positive{color:#08704c}.negative{color:#a32f2f}.linkbutton{padding:0;border:0;background:none;color:#006b9c;text-decoration:underline}.chart{width:100%;height:auto;min-height:220px;display:block}.legend{display:flex;gap:17px;align-items:center;font-size:12px;color:var(--muted)}.dot{width:11px;height:11px;display:inline-block;margin-right:5px;border-radius:3px}.foot{font-size:12px;color:var(--muted);margin-top:22px}.hidden{display:none!important}details{margin:10px 0;border:1px solid var(--line);border-radius:7px;padding:9px 13px}summary{cursor:pointer;font-weight:600}dialog{border:1px solid #b9ccd5;border-radius:14px;max-width:1100px;width:90vw;max-height:90vh;padding:26px}dialog::backdrop{background:#0d283c88}.dialoghead{display:flex;justify-content:space-between;align-items:center;gap:20px}.diagnostic{border-left:3px solid #bd783e;padding:8px 14px;background:#fff7eb;margin:13px 0}footer{border-top:1px solid var(--line);padding-top:15px}.mono{font-family:ui-monospace,Consolas,monospace;font-size:12px}.empty{padding:22px;color:var(--muted)}@media(max-width:850px){.grid{grid-template-columns:1fr 1fr}.two{grid-template-columns:1fr}header{padding:25px}main{padding:18px}.panel{padding:15px}.toolbar input{min-width:170px}}@media print{nav,.toolbar,dialog{display:none}.hidden{display:block!important}.table-scroll{max-height:none;overflow:visible}.panel{break-inside:avoid}header{background:white;color:black}header p{color:#456}}
@media(max-width:1100px){.two{grid-template-columns:1fr}}
</style>
<header><div class="eyebrow">Étude reproductible · ROMEO · GH200</div><h1>HPC Forest : ce qui a changé,<br>ce qui a vraiment été mesuré.</h1><p>Sept campagnes, chaque essai conservé et les programmes valides rejoués sur un même GPU. Les décisions du moteur, les modifications de code et les mesures restent reliées à leurs preuves.</p></header>
<main><nav id="nav" aria-label="Sections"></nav>
<section id="overview"></section><section id="campaigns" class="hidden"></section><section id="programs" class="hidden"></section><section id="trials" class="hidden"></section><section id="engines" class="hidden"></section>
<footer class="foot"><a href="RAPPORT.md">Rapport détaillé</a> · <a href="tables/campagnes.csv">Campagnes CSV</a> · <a href="tables/programmes-remesures.csv">Programmes CSV</a> · <a href="tables/essais-avec-remesures.csv">Tous les essais CSV</a><br><span id="stamp"></span> · Sans dépendance réseau. Les traces historiques ne sont jamais présentées comme de nouvelles recherches avec Mother.</footer></main>
<dialog id="detail"><div class="dialoghead"><h2 id="detailtitle"></h2><button onclick="document.getElementById('detail').close()" aria-label="Fermer le détail">Fermer</button></div><div id="detailbody"></div></dialog>
<script type="application/json" id="study">__STUDY_DATA__</script>
<script>
'use strict';
const D=JSON.parse(document.getElementById('study').textContent), byId=Object.fromEntries(D.programs.map(p=>[p.id,p]));
const esc=x=>String(x??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const f=(x,n=3)=>x==null?'—':Number(x).toLocaleString('fr-FR',{minimumFractionDigits:n,maximumFractionDigits:n});
const ms=x=>x==null?'—':f(x*1000,6),short=x=>x?x.slice(0,7):'—';
const badge=x=>`<span class="badge ${['incorrect','infrastructure_error','generation_failed'].includes(x)?'bad':x==='en cours'?'pending':''}">${esc(x)}</span>`;
const delta=x=>x==null?'—':`<span class="${x>=0?'positive':'negative'}">${x>=0?'+':''}${f(x,2)} %</span>`;
const table=(heads,rows)=>`<div class="table-scroll"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>${rows.length?'':'<div class="empty">Aucun résultat avec ces filtres.</div>'}</div>`;
const option=()=>'<option value="">Toutes les campagnes</option>'+D.campaigns.map(c=>`<option value="${c.campaign}">${c.campaign} — ${esc(c.label)}</option>`).join('');
const tr=values=>'<tr>'+values.map(x=>'<td>'+x+'</td>').join('')+'</tr>';
const sourceLink=id=>`<button class="linkbutton mono" onclick="programDetail('${id}')">${id}</button>`;
const tabs=[['overview','Vue d’ensemble'],['campaigns','Campagnes'],['programs','Programmes'],['trials','Essais & diagnostics'],['engines','Commits & tests']];
document.getElementById('nav').innerHTML=tabs.map(([id,label],i)=>`<button id="nav-${id}" class="${i?'':'active'}" onclick="tab('${id}')">${label}</button>`).join('');
function tab(id){for(const [k]of tabs){document.getElementById(k).classList.toggle('hidden',k!==id);document.getElementById('nav-'+k).classList.toggle('active',k===id)}}
document.getElementById('stamp').textContent='État du dossier : '+D.stamp;

function bars(){let s='<svg class="chart" viewBox="0 0 760 345" role="img" aria-label="Temps des gagnants historiques et temps du rejeu commun, échelle logarithmique">';
const xmin=Math.log10(.07),xmax=Math.log10(2),scale=x=>110+(Math.log10(x*1000)-xmin)/(xmax-xmin)*550;
for(const x of [.1,.2,.5,1,2]){const p=scale(x/1000);s+=`<line x1="${p}" y1="20" x2="${p}" y2="305" stroke="#e1e8ec"/><text x="${p}" y="328" text-anchor="middle" fill="#567" font-size="12">${f(x,1)} ms</text>`}
D.campaigns.forEach((c,i)=>{let y=35+i*40;s+=`<text x="10" y="${y+10}" font-size="13" fill="#123">${c.campaign}</text>`;s+=`<rect x="110" y="${y-4}" width="${Math.max(1,scale(c.historical_seconds)-110)}" height="9" rx="3" fill="#a8bac3"><title>Historique : ${ms(c.historical_seconds)} ms</title></rect>`;if(c.replay_seconds!=null)s+=`<rect x="110" y="${y+9}" width="${Math.max(1,scale(c.replay_seconds)-110)}" height="9" rx="3" fill="#087cba"><title>Rejeu : ${ms(c.replay_seconds)} ms</title></rect><text x="${scale(c.replay_seconds)+8}" y="${y+18}" font-size="11" fill="#07557d">${f(c.replay_seconds*1000,3)}</text>`});return s+'</svg>'}
function overview(){const good=D.programs.filter(p=>p.fully_measured),ranked=[...good].sort((a,b)=>a.mean_seconds-b.mean_seconds),best=ranked[0];
document.getElementById('overview').innerHTML=`<div class="grid">${[['19','commits reconstruits'],['7','campagnes historiques'],['124','programmes distincts récupérés'],[good.length+'/124','programmes remesurés intégralement']].map(([v,l])=>`<div class="card"><div class="stat">${v}</div><p>${l}</p></div>`).join('')}</div>
<div class="notice"><b>${best?'Meilleur temps du rejeu : '+ms(best.mean_seconds)+' ms ('+f(best.speedup,2)+'×).':'Les mesures fraîches sont en cours.'}</b> Les améliorations du moteur et la vitesse des programmes sont évaluées séparément.</div>
<div class="two"><div class="panel"><h2>Les gagnants des sept campagnes</h2><div class="legend"><span><i class="dot" style="background:#a8bac3"></i>Confirmation historique</span><span><i class="dot" style="background:#087cba"></i>Rejeu commun</span></div>${bars()}<p class="foot">Plus court = plus rapide. Axe logarithmique. Les deux séries restent identifiées ; aucune valeur historique ne remplit une mesure manquante.</p></div>
<div class="panel"><h2>Ce que l’étude établit</h2><h3>Les progrès ne sont pas monotones</h3><p>Le meilleur programme historique vient de 776048. Ajouter mémoire, diagnostics ou critique du plan ne garantit pas un meilleur résultat à chaque recherche.</p><h3>Des correctifs ont un effet démontré</h3><p>Les tests identiques avant/après reproduisent la perte du code lorsque les leçons sont absentes, l’absence de bilan mémoire factuel et une réserve insuffisante avant la critique.</p><h3>L’exploration et les incidents restent déterminants</h3><p>Les sujets, le nombre d’essais et les interruptions varient entre campagnes. Les traces permettent de les décrire, sans isoler causalement chaque facteur.</p></div></div>
${D.complete?`<div class="panel"><h2>Des changements précis, des effets différents</h2><p><b>776048 — racine inverse :</b> le remplacement de <code>sqrtf</code> et de la division par <code>rsqrtf</code> réduit le temps de <b>24,40 %</b>, avec un gain dans les cinq blocs. La suppression suivante de la masse cible apporte seulement <b>0,62 %</b> en moyenne et perd dans un bloc.</p><p><b>780448 — deux cibles par thread :</b> le temps augmente de <b>70,79 %</b>. Le réglage du bloc à 128 threads, sans changement de kernel, réduit au contraire le temps de <b>3,21 %</b> par rapport à sa base.</p><p class="muted">Les 630 échantillons sont vérifiés depuis 1 890 latences par taille. La référence de contrôle varie de 0,116 % sur toute la série. Le <a href="RAPPORT.md">rapport</a> détaille les patches, les dispersions et les limites ; les <a href="tables/transitions-par-bloc.csv">transitions par bloc</a> conservent tous les chiffres.</p></div>`:''}
<div class="panel"><h2>Lecture des preuves</h2><p><b>124 programmes</b> sont récupérés à partir de <b>152 évaluations valides</b>, avec toutes leurs origines. Les <b>138 essais</b> incluent aussi les erreurs et les programmes incorrects. Quatre campagnes utilisent un moteur intermédiaire qui n’existe pas comme commit identique.</p><p class="muted">Les programmes sont rejoués sans appel de modèle. Les tests fonctionnels des moteurs ne sont pas de nouvelles campagnes de recherche. Aucune régularité de Mother n’est déduite d’un seul lancement.</p></div>`}

function progressChart(id){const rows=D.trials.filter(r=>r.campaign===id&&r.seconds!=null&&r.measured_elapsed_seconds!=null).sort((a,b)=>a.measured_elapsed_seconds-b.measured_elapsed_seconds);if(!rows.length)return '';
const W=850,H=290,lo=Math.log10(Math.min(...rows.map(r=>r.seconds*1000))*.8),hi=Math.log10(Math.max(...rows.map(r=>r.seconds*1000))*1.3),x=t=>55+t/1800*735,y=v=>235-(Math.log10(v*1000)-lo)/(hi-lo)*205;
let svg=`<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Temps mesurés historiquement selon le moment de fin d’évaluation">`;
for(const m of [0,5,10,15,20,25,30])svg+=`<line x1="${x(m*60)}" y1="25" x2="${x(m*60)}" y2="235" stroke="#e5ebee"/><text x="${x(m*60)}" y="260" text-anchor="middle" font-size="11" fill="#567">${m} min</text>`;
for(let v of [.01,.03,.1,.3,1,3,10,30])if(Math.log10(v)>=lo&&Math.log10(v)<=hi)svg+=`<line x1="55" y1="${y(v/1000)}" x2="790" y2="${y(v/1000)}" stroke="#e5ebee"/><text x="47" y="${y(v/1000)+4}" text-anchor="end" font-size="11" fill="#567">${v} ms</text>`;
const color={T1:'#087cba',T2:'#c77321',T3:'#7452a8',T4:'#14895e',G:'#d5314b'};let best=Infinity,points=[];
for(const r of rows){best=Math.min(best,r.seconds);points.push(`${x(r.measured_elapsed_seconds)},${y(best)}`);svg+=`<circle cx="${x(r.measured_elapsed_seconds)}" cy="${y(r.seconds)}" r="${r.role==='G'?6:4}" fill="${color[r.role]||'#567'}"><title>${r.role} · ${r.id} · ${ms(r.seconds)} ms · ${esc(r.change_kind)}</title></circle>`}
svg+=`<polyline points="${points.join(' ')}" fill="none" stroke="#344b58" stroke-dasharray="4 4" opacity=".55"/>`;return svg+'</svg>'}
function campaigns(){document.getElementById('campaigns').innerHTML=`<h2>Déroulement des campagnes</h2><div class="toolbar"><label for="campaignChoice">Campagne</label><select id="campaignChoice" onchange="campaignCard()">${D.campaigns.map(c=>`<option value="${c.campaign}">${c.campaign} — ${esc(c.label)}</option>`).join('')}</select></div><div id="campaignCard"></div>`;campaignCard()}
function campaignCard(){const id=document.getElementById('campaignChoice').value,c=D.campaigns.find(c=>c.campaign===id),rows=D.trials.filter(r=>r.campaign===id),map=D.provenance.find(p=>p.campaign===id).payload_matches[0];
document.getElementById('campaignCard').innerHTML=`<div class="panel"><h2>${id} · ${esc(c.label)}</h2><p>${esc(c.observation)}</p><div class="grid">${[[c.trees,'arbres choisis'],[c.trials,'essais de recherche'],[c.valid,'essais valides'],[f(c.duration_seconds/60,1)+' min','durée historique']].map(([v,l])=>`<div><div class="stat">${v}</div><small>${l}</small></div>`).join('')}</div><h3>Progression historique</h3>${progressChart(id)}<p class="foot">Points : évaluations terminées, temps historiques. Rouge : intégration G ; autres couleurs : arbres. Trait pointillé : meilleur résultat déjà mesuré. Les secondes de compilation et les appels du modèle ne sont pas des temps de kernel.</p><h3>Gagnant conservé pour la comparaison</h3><p>${sourceLink(c.winner_variant)} · Historique : <b>${ms(c.historical_seconds)} ms</b> · Rejeu : <b>${ms(c.replay_seconds)} ms</b></p><details><summary>Provenance du moteur</summary><p>Empreinte : <code>${c.engine_identity}</code></p><p>${map.normalized_matching_commits.length?'Correspondance Git : '+map.normalized_matching_commits.map(short).join(', '):'État intermédiaire sans commit identique. Différences avec le commit le plus proche : '+map.differences_from_nearest.join(', ')}</p><p>Manifeste vérifié : ${map.manifest_matches?'oui':'non'}</p></details></div>
<div class="panel"><h3>Assemblages et changements réellement observés</h3>${table(['Essai','Modification','Historique (ms)','Gain historique / base','Gain du rejeu / base','Preuve'],rows.filter(r=>r.role==='G').map(r=>tr([`<code>${r.id}</code>`,esc(r.change_kind),ms(r.seconds),delta(r.gain_vs_base_pct),delta(r.replay_gain_vs_base_pct),r.patch?`<a href="${r.patch}">Diff exact</a>`:'—'])))}<p class="foot"><a href="data/campaigns/${id}/events.json">Événements</a> · <a href="data/campaigns/${id}/decisions.json">Décisions</a> · <a href="tables/essais-${id}.csv">Tous les essais</a></p></div>`}

function programs(){document.getElementById('programs').innerHTML=`<h2>124 programmes : mêmes tests, même GPU</h2><p class="muted">Cinq répétitions fraîches par programme. Une entrée peut avoir plusieurs origines ; les copies strictement identiques sont regroupées.</p><div class="toolbar"><label for="programCampaign">Campagne</label><select id="programCampaign" onchange="programRows()">${option()}</select><label for="programSearch">Rechercher</label><input id="programSearch" oninput="programRows()" placeholder="Identifiant, commit, source…"><label for="programSort">Tri</label><select id="programSort" onchange="programRows()"><option value="speed">Plus rapide d’abord</option><option value="date">Ordre d’apparition</option></select></div><div id="programTable"></div>`;programRows()}
function programRows(){let rows=D.programs.filter(p=>{const c=document.getElementById('programCampaign').value,q=document.getElementById('programSearch').value.toLowerCase();return (!c||p.campaigns.includes(c))&&(!q||[p.id,p.source_code,...p.origins.map(o=>o.commit)].join(' ').toLowerCase().includes(q))});
if(document.getElementById('programSort').value==='speed')rows.sort((a,b)=>(a.mean_seconds??Infinity)-(b.mean_seconds??Infinity));
document.getElementById('programTable').innerHTML=table(['Programme','Origines','Statut du rejeu','Moyenne (ms)','Min / max (ms)','Accélération','Lancement'],rows.map(p=>tr([sourceLink(p.id),p.campaigns.join(', '),badge(p.status||'en cours'),ms(p.mean_seconds),`${ms(p.min_seconds)} / ${ms(p.max_seconds)}`,p.speedup?f(p.speedup,2)+'×':'—',`bloc ${p.launch.block} · sorties ${p.launch.items_per_block} · partagé dynamique ${p.launch.shared_memory_bytes} o`])))}
function programDetail(id){const p=byId[id];document.getElementById('detailtitle').textContent='Programme '+id;document.getElementById('detailbody').innerHTML=`<p>${badge(p.status||'en cours')} · moyenne <b>${ms(p.mean_seconds)} ms</b> · accélération <b>${p.speedup?f(p.speedup,2)+'×':'—'}</b></p><p><small>SHA-256 du kernel : <code>${p.source_sha256}</code></small></p><h3>Échantillons frais</h3><p>${p.samples?p.samples.map(ms).join(' · ')+' ms':'En attente'}</p><h3>Origines conservées</h3>${table(['Campagne','Essai','Phase','Commit','Temps historique (ms)'],p.origins.map(o=>tr([o.job_id,`<code>${esc(o.experiment_id)}</code>`,o.phase,`<code>${short(o.commit)}</code>`,ms(o.historical_seconds)])))}<h3>Lancement</h3><pre>${esc(JSON.stringify(p.launch,null,2))}</pre><h3>Source exacte</h3><pre>${esc(p.source_code)}</pre><p><a href="sources/${p.id}/src/nbody_kernel.cu">Fichier CUDA</a> · <a href="sources/${p.id}/src/launch.json">launch.json</a> · <a href="gpu/results/records/${p.id}.json">Tous les contrôles et mesures</a></p>`;document.getElementById('detail').showModal()}

function trials(){document.getElementById('trials').innerHTML=`<h2>138 essais, y compris les échecs</h2><p class="muted">Le temps et le score des erreurs d’infrastructure restent absents. Une correction de code n’est pas supposée parce qu’une hypothèse le déclare.</p><div class="toolbar"><label for="trialCampaign">Campagne</label><select id="trialCampaign" onchange="trialRows()">${option()}</select><label for="trialState">Statut</label><select id="trialState" onchange="trialRows()"><option value="">Tous</option><option>valid</option><option>incorrect</option><option>infrastructure_error</option><option>generation_failed</option></select><label for="trialRole">Arbre</label><select id="trialRole" onchange="trialRows()"><option value="">Tous</option><option>T1</option><option>T2</option><option>T3</option><option>T4</option><option>G</option></select></div><div id="trialTable"></div>`;trialRows()}
function trialRows(){const c=document.getElementById('trialCampaign').value,s=document.getElementById('trialState').value,role=document.getElementById('trialRole').value;const rows=D.trials.filter(r=>(!c||c===r.campaign)&&(!s||s===r.status)&&(!role||role===r.role));document.getElementById('trialTable').innerHTML=table(['Campagne / essai','Arbre / profondeur','Statut','Historique (ms)','Rejeu (ms)','Modification','Diagnostic'],rows.map(r=>tr([`${r.campaign}<br><button class="linkbutton mono" onclick="trialDetail('${r.campaign}','${r.id}')">${r.id}</button>`,`${r.role} / ${r.depth??'—'}`,badge(r.status),ms(r.seconds),ms(r.replay_seconds),esc(r.change_kind),esc((r.reason||'').slice(0,120))])))}
function trialDetail(job,id){const r=D.trials.find(r=>r.campaign===job&&r.id===id);document.getElementById('detailtitle').textContent=job+' / '+id;document.getElementById('detailbody').innerHTML=`<p>${badge(r.status)} · ${r.role} · profondeur ${r.depth??'—'}</p><div class="diagnostic">${esc(r.reason||'Aucun motif d’erreur enregistré.')}</div><h3>Hypothèse déclarée</h3><p>${esc(r.hypothesis||'Non renseignée')}</p><h3>Observation des fichiers</h3><p>${esc(r.change_kind)} · ${esc((r.changed_paths||[]).join(', '))}</p><p>Gain historique / base : ${delta(r.gain_vs_base_pct)} · Gain du rejeu / base : ${delta(r.replay_gain_vs_base_pct)}</p><p>${r.patch?`<a href="${r.patch}">Diff exact avec la base</a>`:''} ${r.variant_id?' · '+sourceLink(r.variant_id):''}</p><details><summary>Enregistrement complet</summary><pre>${esc(JSON.stringify(r,null,2))}</pre></details>`;document.getElementById('detail').showModal()}

function engines(){const by=Object.fromEntries(D.engines.map(e=>[e.commit,e]));document.getElementById('engines').innerHTML=`<h2>Chronologie du moteur et vérifications</h2><p class="muted">Les tests propres à chaque version valident son comportement fonctionnel. Leur nombre varie avec la couverture ; ce n’est pas une mesure de qualité des recherches générées.</p><div class="panel">${table(['Date','Commit','Évolution enregistrée','Tests : réussis / total','Échecs','Ruff'],D.commits.map(c=>{const e=by[c.commit],s=e?.test_suites?.[0],total=Number(s?.tests||0),fail=Number(s?.failures||0)+Number(s?.errors||0),skip=Number(s?.skipped||0),ruff=e?.commands.find(x=>x.check==='ruff');return tr([new Date(c.date).toLocaleString('fr-FR',{timeZone:'Europe/Paris',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}),`<code>${short(c.commit)}</code>`,esc(c.subject),e?(total-fail-skip)+' / '+total:c.code_or_test_change?'en cours':'moteur inchangé',e?fail:'—',ruff?ruff.exit_code===0?'OK':'Échec':'—'])}))}</div><div class="panel"><h2>Diagnostics des suites</h2>${D.engines.filter(e=>e.failures?.length).map(e=>`<details><summary>${short(e.commit)} : ${e.failures.length} échec(s)</summary>${e.failures.map(f=>`<h3>${esc(f.name)}</h3><pre>${esc(f.diagnostic)}</pre>`).join('')}<a href="engine-tests-isolated/${short(e.commit)}/pytest.log">Journal complet</a></details>`).join('')||'<p>Aucun échec dans les suites terminées.</p>'}</div><div class="panel"><h2>Tests identiques avant / après</h2><p>Un module absent avant une fonctionnalité est indiqué comme tel. Il ne compte pas comme un défaut reproduit dans une interface déjà existante.</p>${D.regressions.map(r=>`<details><summary>${esc(r.case)} · ${r.phase==='before'?'avant':'après'} · ${short(r.engine_commit)} · sortie ${r.exit_code}</summary><p>Suites : ${esc(JSON.stringify(r.suites.map(s=>({tests:s.tests,failures:s.failures,errors:s.errors}))))}</p>${r.failures.map(f=>`<pre>${esc(f.details)}</pre>`).join('')}<a href="regression-tests/${r.case}/${r.phase}/pytest.log">Journal complet</a></details>`).join('')}</div>`}
overview();campaigns();programs();trials();engines();
</script></html>'''
